import "@fontsource/noto-sans-kr";

export const inter = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--flow-px` / `--flow-py` (each −1…1) on the referenced element —
 * the weightless depth of the hero wordmark over the river. styles.css
 * multiplies these into capped translations at three depths: the far kicker
 * barely moves, the title carries the drift, the nearest glyphs read at
 * arm's length. The lerp is deliberately slower than a tracking parallax
 * (0.045 vs the usual 0.08): the title does not chase the pointer, it
 * settles after it — the same weightless read as drift on water.
 *
 * Fine pointers only — on touch the layers simply rest (the canvas river
 * carries the motion instead), and under reduced motion this hook does
 * nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--flow-px", x.toFixed(4));
      el.style.setProperty("--flow-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      // Guard: a zero-size rect would divide to Infinity; bail to neutral.
      if (r.width < 1 || r.height < 1) return;
      const nx = ((ev.clientX - r.left) / r.width) * 2 - 1;
      const ny = ((ev.clientY - r.top) / r.height) * 2 - 1;
      tx = Number.isFinite(nx) ? Math.max(-1, Math.min(1, nx)) : 0;
      ty = Number.isFinite(ny) ? Math.max(-1, Math.min(1, ny)) : 0;
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--flow-px");
      el.style.removeProperty("--flow-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-in` class. The pre-reveal state (opacity/translate) lives
 * in styles.css and is gated behind the `.flow-js` root class, so the
 * content is fully visible when JavaScript never runs.
 *
 * Elements that intersect in the same observer batch are staggered 90ms
 * apart via transition-delay — the page drifts in, it does not pop.
 */
export function useReveal<T extends HTMLElement>(disabled: boolean) {
  const rootRef = useRef<T | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (disabled || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-in");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 90}ms`;
          el.classList.add("is-in");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.12, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [disabled]);

  return rootRef;
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Drives a 0→1 scroll progress for a pinned chashitsu (tea-preparation
 * scene), written to the element as the `--ch-scrub` custom property. The
 * chasen whisk consumes it in CSS:
 *   stroke-dashoffset: calc(1 - var(--ch-scrub, 1))
 * on pathLength=1 bamboo-tine paths — so the whisk draws exactly as far as
 * the guest has scrolled, and the bowl's matcha surface blooms in only as
 * the preparation completes. The whole ceremony is paced so the whisk never
 * moves faster than the hand that summoned it.
 *
 * Discipline (rubric gate G3):
 * - All geometry is measured inside rAF: one getBoundingClientRect read,
 *   then one custom-property write — read before write, no layout thrash.
 * - The raw progress is lerp-smoothed with a dt-normalized factor
 *   (1 - 0.88^(dt/16.7)), so a 120Hz display does not scrub twice as fast
 *   as a 60Hz one. Half-life ≈ 5.4 frames.
 * - An IntersectionObserver starts/stops the loop, so an offscreen
 *   chashitsu costs zero frames. A visibilitychange listener also stops it
 *   when the tab is hidden.
 * - Disabled (reduced motion) or never mounted (no JS): the hook writes
 *   `--ch-scrub: 1` once and the CSS default of 1 leaves every tine drawn
 *   and the bowl full — a completed preparation, statically waiting.
 */
export function useScrollProgress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    if (disabled) {
      el.style.setProperty("--ch-scrub", "1");
      return;
    }

    let raf = 0;
    let last = 0;
    let value: number | null = null;

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      const dt = Math.min(Math.max(now - last, 1), 48);
      last = now;

      // Read phase: one rect, one viewport height.
      const rect = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;

      // The scrub runs from "scene center at 62% of the viewport" across
      // 90% of the scene's height, capped at ~1.2 viewports so tall
      // single-column (mobile) chashitsu still finish while in view.
      const center = rect.top + rect.height / 2;
      const span = Math.max(Math.min(rect.height * 0.9, vh * 1.2), 1);
      const raw = (vh * 0.62 - center) / span;
      const target = Math.min(1, Math.max(0, raw));

      if (value === null) {
        value = target; // first frame: no animated catch-up flash
      } else {
        value += (target - value) * (1 - Math.pow(0.88, dt / 16.7));
        if (Math.abs(target - value) < 0.0005) value = target;
      }

      // Write phase.
      el.style.setProperty("--ch-scrub", value.toFixed(4));
    };

    const start = () => {
      if (raf) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };
    const stop = () => {
      if (!raf) return;
      cancelAnimationFrame(raf);
      raf = 0;
    };

    const onVisibility = () => {
      if (document.hidden) stop();
      else start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    if (!("IntersectionObserver" in window)) {
      start();
      return () => {
        stop();
        document.removeEventListener("visibilitychange", onVisibility);
      };
    }

    const io = new IntersectionObserver(
      (hits) => {
        for (const hit of hits) {
          if (hit.isIntersecting) start();
          else stop();
        }
      },
      { rootMargin: "25% 0px 25% 0px" },
    );
    io.observe(el);

    return () => {
      stop();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";
import "./styles.css";
import { inter, notoSansKR } from "./fonts";
import FlowHero from "./components/FlowHero";
import FlowingVerse from "./components/FlowingVerse";
import FlowLaws from "./components/FlowLaws";
import FlowFooter from "./components/FlowFooter";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

/**
 * FLOW — 흐름, 글자의 강. A journaling app whose whole identity is that
 * letters flow like water. The hero wordmark drifts in over a living canvas
 * river (char-split-reveal, each glyph settling sideways); a pinned verse
 * section holds while four stanzas flow past with the scroll
 * (scroll-scrub-pinned); and the title leans gently toward the pointer
 * over the river (pointer-parallax). The feature section names five real
 * laws of liquid — rheology, surface tension, laminar flow, turbulence,
 * viscosity — and reads each as a law of writing.
 *
 * `flow-js` is added on mount; without JS the page is a finished, readable
 * journal — the river replaced by a CSS sky wash, the verses stacked in
 * full, the laws a static list. The whole entry is pure code: no images,
 * no audio, no dependencies beyond the two fontsource families.
 */
export default function FlowPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  // One reveal observer on the root scrolls every [data-reveal] in as it
  // enters — the sections opt in individually by carrying the attribute.
  const revealRef = useReveal<HTMLDivElement>(reduced);

  useEffect(() => {
    // Imperative on purpose: the class signals to CSS that JS is alive, and
    // never changes once set. SSR markup stays the finished page.
    rootRef.current?.classList.add("flow-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "flow" }, "*");
  }, []);

  return (
    <div
      id="flow-top"
      ref={rootRef}
      className={`${inter.variable} ${notoSansKR.variable} flow-root`}
    >
      <div ref={revealRef} className="flow-sky">
        <FlowHero />
        <main>
          <FlowingVerse />
          <FlowLaws />
        </main>
        <FlowFooter />
      </div>
    </div>
  );
}

/* ==========================================================================
   FLOW 흐름 — 글자의 강 · river of words
   liquid / organic · sky / paper / drift · letters flow like water
   Scoped by convention to .flow-root; classes prefixed flow-.
   The water is drawn in code: a canvas river carries the words, a pinned
   verse section holds while stanzas flow past, and a feature section names
   the laws of liquid. No images, no audio, no dependencies.
   ========================================================================== */

.flow-root {
  /* ==========================================================================
     -- palette ---------------------------------------------------------------
     A sky-and-paper palette tuned to liquid. The bright cyans are
     decorative (large/glyph use only — they fail AA against the pale sky);
     body copy stays on the deep navy inks, which clear AAA. Every token
     carries its contrast ratio and its role, the gallery rule.
     ========================================================================== */
  --flow-bg: #f0f9ff;            /* sky at rest — page surface */
  --flow-bg-deep: #e0f2fe;       /* paper at depth — verse well */
  --flow-bg-darker: #bae6fd;     /* the deeper current — section wash */
  --flow-ink: #0c4a6e;           /* primary text — 8.87:1 on sky (AAA) */
  --flow-ink-soft: #0369a1;      /* secondary text — 5.57:1 on sky (AA), 5.17:1 on paper (AA) */
  --flow-ink-faint: #7dd3fc;     /* decorative far-band ink — 1.78:1 on sky, LARGE/GLYPH ONLY */
  --flow-accent: #0ea5e9;        /* accent — DECORATIVE ONLY (2.60:1 on sky), large/glyph use */
  --flow-accent-press: #075985;  /* solid fills, ink-on-accent: 7.09:1 on sky (AAA), white-on-it 7.74:1 (AAA) */
  --flow-accent-deep: #0c4a6e;   /* near-band canvas ink — same as primary, AAA on sky */
  --flow-accent-soft: rgba(14, 165, 233, 0.18);  /* hairlines, never text */
  --flow-accent-glass: rgba(14, 165, 233, 0.06); /* card surface wash */
  --flow-paper-wash: rgba(255, 255, 255, 0.62);  /* glass card fill over sky */
  --flow-paper-wash-deep: rgba(240, 249, 255, 0.5); /* glass card fill over paper */

  /* -- canvas palette (read by wordRiver.ts via readPalette) -------------- */
  --flow-canvas-sky: #f0f9ff;    /* the river's surface — matches the page */
  --flow-canvas-far: #7dd3fc;    /* far-band words — faint cool (DECORATIVE) */
  --flow-canvas-mid: #0284c7;    /* mid-band words — readable teal (3.86:1 on sky, LARGE) */
  --flow-canvas-near: #0c4a6e;   /* near-band words — crisp navy (8.87:1 on sky AAA) */

  /* -- type ---------------------------------------------------------------- */
  --flow-font: "Inter", "Noto Sans KR", sans-serif;
  --flow-font-ko: "Noto Sans KR", "Inter", sans-serif;
  --flow-font-display: "Inter", "Noto Sans KR", sans-serif;

  /* -- spacing (4px baseline) --------------------------------------------- */
  --flow-space-1: 0.25rem;   /*  4px */
  --flow-space-2: 0.5rem;    /*  8px — base unit */
  --flow-space-3: 0.75rem;   /* 12px */
  --flow-space-4: 1rem;      /* 16px */
  --flow-space-6: 1.5rem;    /* 24px */
  --flow-space-8: 2rem;      /* 32px */
  --flow-space-12: 3rem;     /* 48px */
  --flow-space-16: 4rem;     /* 64px */
  --flow-space-24: 6rem;     /* 96px */

  /* -- motion ---------------------------------------------------------------
     Three curves: drift for the slow entrance/reveal of letters (strong
     ease-out), current for the long horizontal drift of the verses, spring
     for the snappy micro-interactions on cards and words (soft back). */
  --flow-ease-drift:   cubic-bezier(0.16, 1, 0.3, 1);     /* strong ease-out — entrance/reveal */
  --flow-ease-current: cubic-bezier(0.25, 1, 0.5, 1);     /* ease-out-quart — long horizontal drift */
  --flow-ease-spring:  cubic-bezier(0.34, 1.56, 0.64, 1); /* soft back — hover/press */

  /* -- shared radii -------------------------------------------------------- */
  --flow-radius: 18px;
  --flow-radius-lg: 24px;

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background:
    linear-gradient(180deg, var(--flow-bg) 0%, var(--flow-bg-deep) 100%);
  color: var(--flow-ink);
  font-family: var(--flow-font);
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.75;
  overflow-x: hidden;
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

.flow-root,
.flow-root *,
.flow-root *::before,
.flow-root *::after {
  box-sizing: border-box;
}

.flow-root h1,
.flow-root h2,
.flow-root h3,
.flow-root h4,
.flow-root p,
.flow-root ol,
.flow-root ul {
  margin: 0;
}

.flow-root ol,
.flow-root ul {
  padding: 0;
  list-style: none;
}

/* Korean is first-class: its own typeface and rhythm, words kept whole.
   The gallery rule — line-height 1.9 (vs Latin 1.7), letter-spacing 0
   (no tracking), word-break keep-all (no mid-word breaks). */
.flow-root :lang(ko) {
  font-family: var(--flow-font-ko);
  letter-spacing: 0;
  line-height: 1.9;
  word-break: keep-all;
  overflow-wrap: break-word;
}

.flow-root em {
  font-family: var(--flow-font-display);
  font-style: italic;
  letter-spacing: 0.01em;
}

.flow-root ::selection {
  background: var(--flow-accent);
  color: #fff;
}

.flow-root :focus-visible {
  outline: 2px solid var(--flow-accent-press);
  outline-offset: 3px;
  border-radius: 3px;
  box-shadow: 0 0 0 6px rgba(7, 89, 133, 0.15);
}

.flow-sky {
  position: relative;
}

/* ==========================================================================
   Water surface — two layered ambient textures, both pure CSS:
   1. two concentric caustic blooms that breathe at different rates
   2. a slow vertical depth wash that holds the whole sky together
   The canvas river paints its own surface, so this is only the ambient
   wash that sits behind everything (the river's deeper current).
   ========================================================================== */

.flow-root::before {
  content: "";
  position: fixed;
  inset: -20%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(40% 30% at 30% 20%, rgba(14, 165, 233, 0.07), transparent 60%),
    radial-gradient(45% 35% at 75% 70%, rgba(7, 89, 133, 0.06), transparent 60%),
    radial-gradient(50% 40% at 50% 110%, rgba(14, 165, 233, 0.05), transparent 65%);
  animation: flow-surface 18s var(--flow-ease-drift) infinite alternate;
}

@keyframes flow-surface {
  to { transform: translate3d(2%, -1%, 0) scale(1.04); }
}

@media (prefers-reduced-motion: reduce) {
  .flow-root::before { animation: none; }
}

/* ==========================================================================
   Reveal gating
   --------------------------------------------------------------------------
   Pre-reveal state exists only when JS is alive (gated behind .flow-js),
   so the SSR / no-JS markup is the finished, readable journal. Stagger is
   applied per-batch in the hook via transition-delay.
   ========================================================================== */

.flow-js [data-reveal] {
  opacity: 0;
  transform: translateY(24px);
  transition:
    opacity 900ms var(--flow-ease-drift),
    transform 900ms var(--flow-ease-drift);
  will-change: opacity, transform;
}
.flow-js [data-reveal].is-in {
  opacity: 1;
  transform: translateY(0);
}
@media (prefers-reduced-motion: reduce) {
  .flow-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

/* ==========================================================================
   Shared kicker — the bilingual section label
   ========================================================================== */

.flow-kicker {
  font-size: clamp(0.66rem, 0.9vw, 0.74rem);
  text-transform: uppercase;
  letter-spacing: 0.24em;
  color: var(--flow-accent-press);
  margin: 0 0 var(--flow-space-6);
  font-weight: 500;
}
.flow-kicker :lang(ko) {
  text-transform: none;
  letter-spacing: 0;
  font-weight: 600;
}

/* ==========================================================================
   Hero — the arrival; the river carries the wordmark
   --------------------------------------------------------------------------
   The hero is the river's frame. The canvas fills it as a living backdrop;
   a soft sky veil keeps the wordmark's negative space readable regardless
   of which words drift past; and the title floats over the top at three
   depths of its own via the pointer-parallax hook.
   ========================================================================== */

.flow-hero {
  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  overflow: hidden;
  isolation: isolate;
}

/* The canvas river fills the hero as a living backdrop. */
.flow-hero__river {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none; /* the canvas listens on window; the hero stays scrollable */
}

/* A soft sky wash over the river's top and bottom so the wordmark always
   has readable negative space. Decorative only. */
.flow-hero__veil {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(180deg,
      var(--flow-bg) 0%,
      rgba(240, 249, 255, 0.55) 18%,
      transparent 38%,
      transparent 62%,
      rgba(224, 242, 254, 0.55) 82%,
      var(--flow-bg-deep) 100%);
}

/* The hero copy sits above the river and veil. The whole block leans with
   the pointer (three depths, multiplied below). */
.flow-hero__copy {
  position: relative;
  z-index: 2;
  text-align: center;
  padding:
    clamp(80px, 18vh, 160px)
    clamp(20px, 5vw, 60px)
    clamp(60px, 12vh, 120px);
  max-width: 1100px;
  /* the lerp-driven depth translate, plus a settle transition */
  transition: transform 600ms var(--flow-ease-drift);
  will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
  .flow-hero__copy { transform: none !important; transition: none; }
}

/* The wordmark — giant FLOW that drifts in glyph by glyph. */
.flow-title {
  font-weight: 700;
  font-size: clamp(4rem, 14vw, 10rem);
  line-height: 0.9;
  letter-spacing: -0.03em;          /* display: tight tracking for the wordmark */
  margin: 0 0 var(--flow-space-6);
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.02em;
  text-wrap: balance;
  color: var(--flow-ink);
  /* the wordmark carries the most pointer drift — the nearest layer */
  transform: translate3d(
    calc(var(--flow-px, 0) * 18px),
    calc(var(--flow-py, 0) * 10px),
    0
  );
}

/* char-split-reveal: each glyph drifts in from the side, staggered. */
.flow-glyph {
  display: inline-block;
  opacity: 0;
  transform: translateX(-40px) skewX(-8deg);
}
.flow-js .flow-glyph {
  animation: flow-glyph-in 1100ms var(--flow-ease-drift) both;
  animation-delay: calc(var(--flow-i, 0) * 140ms + 200ms);
}
@keyframes flow-glyph-in {
  to { opacity: 1; transform: translateX(0) skewX(0); }
}
@media (prefers-reduced-motion: reduce) {
  .flow-glyph { opacity: 1; transform: none; animation: none; }
}

/* The Korean subtitle beneath the wordmark — a quiet second voice. */
.flow-title__ko {
  display: block;
  width: 100%;
  font-size: 0.3em;
  color: var(--flow-ink-soft);
  margin-top: var(--flow-space-2);
  font-weight: 500;
  letter-spacing: 0.08em;           /* Korean subtitle: gentle spacing, not tracked */
  /* the subtitle drifts less than the wordmark — the mid layer */
  transform: translate3d(
    calc(var(--flow-px, 0) * 8px),
    calc(var(--flow-py, 0) * 5px),
    0
  );
}

/* The lede — the page's thesis, held at the centre. */
.flow-sub {
  max-width: 540px;
  margin: 0 auto var(--flow-space-6);
  color: var(--flow-ink-soft);
  font-size: clamp(0.95rem, 1.6vw, 1.15rem);
  line-height: 1.7;
  text-wrap: pretty;
  /* the lede barely moves — the far layer */
  transform: translate3d(
    calc(var(--flow-px, 0) * 4px),
    calc(var(--flow-py, 0) * 2px),
    0
  );
}
.flow-sub__en {
  display: block;
  margin-top: 0.3rem;
  font-style: italic;
}

/* The pointer hint — the only instruction the hero gives. */
.flow-hero__hint {
  font-size: 0.78rem;
  color: var(--flow-ink-soft);
  letter-spacing: 0.04em;
  opacity: 0.85;
}
.flow-hero__hint-en {
  font-style: italic;
}

/* ==========================================================================
   The canvas river
   --------------------------------------------------------------------------
   The wrapper is positioned by its parent (.flow-hero__river); it just
   needs to fill it and own its backing store. The canvas reads its palette
   from the .flow-river host (see readPalette in wordRiver.ts).
   ========================================================================== */

.flow-river {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.flow-river__canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* ==========================================================================
   흐르는 시 · FlowingVerse — the pinned verse where stanzas flow past
   --------------------------------------------------------------------------
   scroll-scrub-pinned. The outer section is tall (400vh — one viewport per
   stanza plus margin); the inner stage is sticky, so the visitor scrolls
   through four verse-heights of the same scene. One value, --flow-scrub
   (0→1), drives every stanza's dissolve. Each stanza owns a quarter of the
   scroll; its dissolve window is centred on its quarter (--flow-c) with a
   soft half-width (--flow-h), so stanzas crossfade rather than cut.
   ========================================================================== */

.flow-verse {
  position: relative;
  /* tall so there is scroll-room to scrub through all four stanzas */
  height: 400vh;
  background:
    radial-gradient(80% 60% at 50% 30%, rgba(14, 165, 233, 0.08), transparent 70%),
    radial-gradient(60% 50% at 50% 100%, rgba(7, 89, 133, 0.07), transparent 70%),
    var(--flow-bg-deep);
  border-top: 1px solid var(--flow-accent-soft);
  border-bottom: 1px solid var(--flow-accent-soft);
  isolation: isolate;
}

.flow-verse__pin {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  max-width: 880px;
  margin-inline: auto;
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 56px);
}

/* The head — kicker, title, lede. Sits above the stanzas. */
.flow-verse__head {
  text-align: center;
  margin-bottom: clamp(1.6rem, 4vh, 2.6rem);
}

.flow-verse__title {
  font-size: clamp(1.6rem, 4vw, 2.6rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;          /* large display heading */
  margin: 0 0 var(--flow-space-4);
  color: var(--flow-ink);
  text-wrap: balance;
}

.flow-verse__lede {
  font-size: clamp(0.92rem, 1.4vw, 1.05rem);
  color: var(--flow-ink-soft);
  max-width: 36rem;
  margin-inline: auto;
}
.flow-verse__lede em {
  display: block;
  font-size: 1.1rem;
  line-height: 1.5;
  margin-bottom: 0.35rem;
}
.flow-verse__lede span {
  display: block;
  color: var(--flow-ink-soft);
  opacity: 0.85;
  font-size: 0.92rem;
}

/* The four stanzas stacked in the same stage; each dissolves with scroll.
   The stage list is relative so all four stanzas occupy the same space. */
.flow-verse__stages {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.flow-verse__stage {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  gap: var(--flow-space-4);
  /* dissolve: opacity is 1 inside the stanza's window, fading at the edges.
     We compute the scroll's signed distance from the window centre and clamp
     it into a 0..1 alpha. The absolute distance is max(d, -d) — supported
     wherever calc()/max()/clamp() are, which is everywhere. The ramp is 1 at
     |d| ≤ h·0.4 and reaches 0 at |d| = h, a soft crossfade, not a cut. */
  --flow-d: calc(var(--flow-scrub, 1) - var(--flow-c, 0.5));
  --flow-ad: max(var(--flow-d), calc(-1 * var(--flow-d)));
  opacity: clamp(
    0,
    calc(1 - (var(--flow-ad) - var(--flow-h, 0.1) * 0.4) / (var(--flow-h, 0.1) * 0.6)),
    1
  );
  transform: translateY(
    calc(var(--flow-d, 0) * 60px)
  );
  transition: opacity 200ms var(--flow-ease-current);
}

/* the small bilingual number above each stanza */
.flow-verse__no {
  font-size: 0.74rem;
  letter-spacing: 0.22em;
  color: var(--flow-accent-press);
  text-transform: uppercase;
  font-weight: 500;
  opacity: 0.8;
}
.flow-verse__no :lang(ko) {
  text-transform: none;
  letter-spacing: 0.12em;
  font-weight: 600;
}
.flow-verse__no-en {
  font-style: italic;
  letter-spacing: 0.06em;
}

/* the lines of a stanza */
.flow-verse__lines {
  display: flex;
  flex-direction: column;
  gap: var(--flow-space-3);
  max-width: 32rem;
}

.flow-verse__line {
  font-size: clamp(1.1rem, 2.6vw, 1.6rem);
  line-height: 1.4;
  font-weight: 500;
  color: var(--flow-ink);
  text-wrap: balance;
}
.flow-verse__ko {
  display: block;
}
.flow-verse__en {
  display: block;
  margin-top: 0.2rem;
  font-style: italic;
  font-weight: 400;
  font-size: 0.72em;
  color: var(--flow-ink-soft);
  letter-spacing: 0.01em;
}

.flow-verse__caption {
  text-align: center;
  font-size: 0.88rem;
  color: var(--flow-ink-soft);
  margin-top: clamp(1.4rem, 3vh, 2.4rem);
  opacity: 0.85;
}
.flow-verse__caption em {
  display: block;
  margin-top: 0.2rem;
}

/* ==========================================================================
   흐름의 법칙 · FlowLaws — the laws of liquid
   --------------------------------------------------------------------------
   Five cards, one per law (rheology, surface tension, laminar, turbulence,
   viscosity). Each is a glass surface over the sky with a layered shadow
   (ambient + key + contact), a thin accent hairline along the top that
   brightens on hover, and a spring lift on hover. The grid is responsive:
   one column on phones, two on tablets, three on desktops.
   ========================================================================== */

.flow-laws {
  position: relative;
  z-index: 1;
  max-width: 1200px;
  margin-inline: auto;
  padding: clamp(72px, 12vh, 140px) clamp(20px, 5vw, 56px);
}

.flow-laws__head {
  max-width: 46rem;
  margin-bottom: clamp(2rem, 5vh, 3.2rem);
}

.flow-laws__title {
  font-size: clamp(1.8rem, 4.4vw, 2.8rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;          /* large display heading */
  margin: 0 0 var(--flow-space-6);
  color: var(--flow-ink);
  text-wrap: balance;
}

.flow-laws__lede {
  font-size: clamp(0.95rem, 1.5vw, 1.1rem);
  color: var(--flow-ink-soft);
  line-height: 1.7;
  max-width: 38rem;
  text-wrap: pretty;
}
.flow-laws__lede em {
  display: block;
  font-size: 1.15rem;
  line-height: 1.5;
  margin-bottom: 0.4rem;
  color: var(--flow-ink);
}
.flow-laws__lede span {
  display: block;
  opacity: 0.9;
}

.flow-laws__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: clamp(20px, 3vw, 32px);
}

/* a single law card — the glass surface */
.flow-law {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--flow-space-4);
  padding: var(--flow-space-8) var(--flow-space-6) var(--flow-space-6);
  border-radius: var(--flow-radius-lg);
  background:
    linear-gradient(180deg, var(--flow-paper-wash) 0%, var(--flow-paper-wash-deep) 100%);
  border: 1px solid var(--flow-accent-soft);
  backdrop-filter: blur(8px) saturate(140%);
  -webkit-backdrop-filter: blur(8px) saturate(140%);
  box-shadow:
    0 1px 2px  rgba(7, 89, 133, 0.05),    /* ambient — surface contact */
    0 8px 18px rgba(7, 89, 133, 0.08),    /* key — primary cast */
    0 24px 48px rgba(7, 89, 133, 0.06);   /* contact — far diffusion */
  transition:
    transform 280ms var(--flow-ease-spring),
    box-shadow 280ms var(--flow-ease-drift),
    border-color 200ms var(--flow-ease-drift);
}

/* a soft accent wash along the top — the implied light source */
.flow-law::before {
  content: "";
  position: absolute;
  top: -1px;
  left: var(--flow-space-6);
  right: var(--flow-space-6);
  height: 3px;
  border-radius: 3px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--flow-accent) 30%,
    var(--flow-accent-press) 70%,
    transparent 100%
  );
  opacity: 0.55;
  transition: opacity 280ms var(--flow-ease-drift);
}

.flow-law:hover {
  transform: translateY(-4px);
  border-color: rgba(14, 165, 233, 0.34);
  box-shadow:
    0 2px 4px  rgba(7, 89, 133, 0.06),
    0 14px 28px rgba(7, 89, 133, 0.12),
    0 36px 64px rgba(7, 89, 133, 0.08);
}
.flow-law:hover::before { opacity: 1; }
.flow-law:focus-within {
  border-color: rgba(14, 165, 233, 0.38);
}

/* the card head — number + name */
.flow-law__head {
  display: flex;
  align-items: baseline;
  gap: var(--flow-space-4);
}

.flow-law__no {
  flex: none;
  font-family: var(--flow-font-display);
  font-size: 0.82rem;
  letter-spacing: 0.18em;
  color: var(--flow-accent);
  font-weight: 600;
}

.flow-law__name {
  flex: 1 1 auto;
  min-width: 0;
}

.flow-law__ko {
  font-size: clamp(1.3rem, 2.4vw, 1.6rem);
  font-weight: 600;
  letter-spacing: 0;                /* Korean: no tracking */
  line-height: 1.2;
  color: var(--flow-ink);
  margin: 0;
}

.flow-law__en {
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  color: var(--flow-ink-soft);
  margin: 0.2rem 0 0;
}
.flow-law__en-term {
  text-transform: uppercase;
  font-weight: 500;
}
.flow-law__rom {
  font-style: italic;
  opacity: 0.8;
}

/* the one-line aphorism — the card's emotional centre */
.flow-law__aphorism {
  font-size: clamp(1rem, 1.6vw, 1.15rem);
  font-weight: 500;
  line-height: 1.5;
  color: var(--flow-accent-press);
  letter-spacing: 0;
  text-wrap: balance;
}
.flow-law__aphorism-en {
  font-style: italic;
  font-size: 0.88rem;
  line-height: 1.5;
  color: var(--flow-ink-soft);
  margin: calc(-1 * var(--flow-space-1)) 0 0; /* tuck under the Korean aphorism */
}

/* the body copy — the science and the image */
.flow-law__body {
  flex: 1 1 auto;
}
.flow-law__body-ko {
  font-size: 0.92rem;
  line-height: 1.85;
  color: var(--flow-ink);
  margin: 0 0 var(--flow-space-3);
  text-wrap: pretty;
}
.flow-law__body-en {
  font-size: 0.9rem;
  line-height: 1.65;
  color: var(--flow-ink-soft);
  margin: 0;
  text-wrap: pretty;
}

/* the detail row — the constant or unit, set in mono numerals */
.flow-law__detail {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--flow-space-3);
  margin-top: var(--flow-space-2);
  padding-top: var(--flow-space-3);
  border-top: 1px solid var(--flow-accent-soft);
  font-size: 0.82rem;
}
.flow-law__detail-label {
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 0.66rem;
  color: var(--flow-ink-soft);
  font-weight: 500;
}
.flow-law__detail-label :lang(ko) {
  text-transform: none;
  letter-spacing: 0.06em;
}
.flow-law__detail-value {
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
  color: var(--flow-accent-press);
  font-weight: 500;
}

.flow-laws__caption {
  max-width: 40rem;
  margin-inline: auto;
  margin-top: clamp(2rem, 5vh, 3.2rem);
  text-align: center;
  font-size: 0.9rem;
  color: var(--flow-ink-soft);
  line-height: 1.7;
}
.flow-laws__caption span {
  display: block;
}
.flow-laws__caption em {
  display: block;
  margin-top: 0.3rem;
  font-size: 0.88rem;
}

/* ==========================================================================
   Footer — the river reaches the sea
   ========================================================================== */

.flow-foot {
  position: relative;
  z-index: 1;
  max-width: 880px;
  margin-inline: auto;
  padding: clamp(72px, 12vh, 130px) clamp(20px, 5vw, 56px) clamp(48px, 8vh, 80px);
  text-align: center;
  border-top: 1px solid var(--flow-accent-soft);
  background: linear-gradient(180deg, var(--flow-bg-deep) 0%, var(--flow-bg) 100%);
}

.flow-foot__call {
  font-family: var(--flow-font-display);
  font-weight: 600;
  font-size: clamp(1.6rem, 4.2vw, 2.4rem);
  line-height: 1.2;
  letter-spacing: 0;                /* Korean: no tracking */
  color: var(--flow-ink);
  margin-bottom: var(--flow-space-4);
  text-wrap: balance;
}

.flow-foot__sub {
  font-size: 1rem;
  color: var(--flow-ink-soft);
  margin-bottom: clamp(2rem, 5vh, 2.8rem);
}

.flow-foot__legal {
  font-size: 0.82rem;
  color: var(--flow-ink-soft);
  letter-spacing: 0.04em;
  margin-bottom: var(--flow-space-2);
}

.flow-foot__colophon {
  font-size: 0.82rem;
  color: var(--flow-ink-soft);
  line-height: 1.7;
  opacity: 0.9;
}
.flow-foot__colophon em {
  display: block;
  margin-top: 0.2rem;
}

/* ==========================================================================
   Composition — responsive drifts at three breakpoints
   --------------------------------------------------------------------------
   The gallery rule: at least three media queries (720 / 900 / 1200). Phones
   collapse the law grid to one column, the title shrinks, and the hero's
   pointer hint hides to reclaim vertical space.
   ========================================================================== */

@media (max-width: 1200px) {
  .flow-laws__grid {
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  }
}

@media (max-width: 900px) {
  .flow-verse {
    height: 360vh;
  }
  .flow-law {
    padding: var(--flow-space-6) var(--flow-space-4);
  }
  .flow-law::before {
    left: var(--flow-space-4);
    right: var(--flow-space-4);
  }
  .flow-title {
    letter-spacing: -0.02em;
  }
}

@media (max-width: 720px) {
  .flow-verse {
    height: 320vh;
  }
  .flow-verse__pin {
    padding: clamp(32px, 8vh, 64px) var(--flow-space-4);
  }
  .flow-laws {
    padding: clamp(56px, 10vh, 96px) var(--flow-space-4);
  }
  .flow-laws__grid {
    grid-template-columns: 1fr;
  }
  .flow-verse__line {
    font-size: clamp(1rem, 4vw, 1.3rem);
  }
}

@media (max-width: 480px) {
  .flow-kicker {
    font-size: 0.66rem;
    letter-spacing: 0.2em;
    margin-bottom: var(--flow-space-6);
  }
  .flow-title__ko {
    margin-top: var(--flow-space-1);
    font-size: 0.28em;
  }
  .flow-hero__hint {
    font-size: 0.72rem;
  }
  .flow-law:hover {
    transform: translateY(-2px); /* gentler lift on a small target */
  }
}

/* ==========================================================================
   Reduced motion — the river, already still.
   --------------------------------------------------------------------------
   Under prefers-reduced-motion: the canvas river composes a single still
   frame (WordRiver draws once at the seed composition), the wordmark does
   not drift in glyph by glyph, the pointer parallax never writes its
   variables (so the title rests at the centre), and the reveal hook adds
   is-in to everything immediately. The verses show their last stanza
   (--flow-scrub defaults to 1 — "all into the same sea").
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .flow-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .flow-glyph { opacity: 1; transform: none; animation: none; }
  .flow-title,
  .flow-title__ko,
  .flow-sub,
  .flow-hero__copy {
    transform: none !important;
  }
  .flow-verse__stage {
    transition: none;
    transform: none;
  }
  /* keep all four stanzas readable in the reduced still — stack them */
  .flow-verse__stage:nth-child(n+2) {
    position: relative;
    inset: auto;
  }
}

/* ==========================================================================
   End of FLOW styles
   ========================================================================== */
